def between_row(r,c):
    row=inp[r]
    return any(row[x]==9 for x in range(c)) and any(row[x]==9 for x in range(c+1,W))
def between_col(r,c):
    col=[inp[y][c] for y in range(H)]
    return any(col[y]==9 for y in range(r)) and any(col[y]==9 for y in range(r+1,H))
